-- Generated by Loom
-- Generator: hub
-- Hash function: sha2
{{ config(materialized='incremental', unique_key='customer_hk', incremental_strategy='merge', merge_exclude_columns=['__record_source', '__loaded_at']) }}
SELECT
    customer_hk,
    customer_id,
    __record_source,
    __loaded_at
FROM (
    SELECT
        customer_hk,
        customer_id,
        __record_source,
        __loaded_at,
        ROW_NUMBER() OVER (
            PARTITION BY customer_hk
            ORDER BY __source_ordinal
        ) AS __rn
    FROM (
        SELECT DISTINCT
            lower(sha2(UPPER(TRIM(CAST(customer_id AS STRING))), 256)) AS customer_hk,
            UPPER(TRIM(CAST(customer_id AS STRING))) AS customer_id,
            'crm' AS __record_source,
            current_timestamp() AS __loaded_at,
            0 AS __source_ordinal
        FROM {{ ref('stg_customers_crm') }}
        WHERE customer_id IS NOT NULL
        UNION ALL
        SELECT DISTINCT
            lower(sha2(UPPER(TRIM(CAST(customer_id AS STRING))), 256)) AS customer_hk,
            UPPER(TRIM(CAST(customer_id AS STRING))) AS customer_id,
            'web' AS __record_source,
            current_timestamp() AS __loaded_at,
            1 AS __source_ordinal
        FROM {{ ref('stg_customers_web') }}
        WHERE customer_id IS NOT NULL
    ) AS combined
) AS ranked
WHERE __rn = 1
